import{_ as e,o as s,c as a,aa as n}from"./chunks/framework.oWfRcsIL.js";const p=JSON.parse('{"title":"Test systems and accounts","description":"Why to test staging systems, how to provide test accounts and what side effects to expect.","frontmatter":{"title":"Test systems and accounts","description":"Why to test staging systems, how to provide test accounts and what side effects to expect."},"headers":[],"relativePath":"getting-started/test-accounts.md","filePath":"getting-started/test-accounts.md"}'),o={name:"getting-started/test-accounts.md"};function i(c,t,r,l,d,h){return s(),a("div",null,[...t[0]||(t[0]=[n(`<h1 id="test-systems-and-accounts" tabindex="-1">Test systems and accounts <a class="header-anchor" href="#test-systems-and-accounts" aria-label="Permalink to &quot;Test systems and accounts&quot;">​</a></h1><h2 id="use-a-staging-system" tabindex="-1">Use a staging system <a class="header-anchor" href="#use-a-staging-system" aria-label="Permalink to &quot;Use a staging system&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">We strongly recommend testing staging systems</p><p>Point syslifters.ai at a staging or test environment, not at production. The agents behave like a real attacker: they create, change and delete data, submit forms, trigger emails and password resets and may lock accounts. On a staging system with test data, none of that affects real users or real data, and no real personal data reaches the AI models.</p></div><p>A good staging system:</p><ul><li>runs the same version and configuration as production;</li><li>contains realistic test data, but no real personal data;</li><li>can be reset or restored if the test leaves it in a bad state;</li><li>sends emails as in production, so flows such as password reset and registration can be tested;</li><li>has payments integrated with the payment provider&#39;s sandbox, so payment flows can be tested without real money.</li></ul><p>If you must test production, agree on that explicitly with the system owner, use dedicated test accounts and expect the side effects listed below.</p><h2 id="test-accounts" tabindex="-1">Test accounts <a class="header-anchor" href="#test-accounts" aria-label="Permalink to &quot;Test accounts&quot;">​</a></h2><p>Most vulnerabilities are behind the login. Provide test accounts so the agents can reach the authenticated parts of the application.</p><p>Enter them in <strong>Test accounts</strong> when you create the project (or later with <strong>Edit accounts</strong> on the <strong>Overview</strong> tab), one account per line:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>alice@example.com:Secret123!:user</span></span>
<span class="line"><span>bob@example.com:Secret456!:user</span></span>
<span class="line"><span>admin@example.com:Secret789!:admin</span></span>
<span class="line"><span>api-client:eyJhbGciOi...:api</span></span></code></pre></div><p>The format is <code>username:password</code> or <code>username:api-token</code>, optionally followed by <code>:role</code>.</p><p><code>role</code> is any short label you choose. It is not checked against a fixed list: write whatever names that account in your application, such as <code>user</code>, <code>admin</code>, <code>billing</code> or <code>read-only API</code>. Agents use the label to tell the accounts apart. Leave it off when the username is enough.</p><ul><li>Use <strong>dedicated test accounts only</strong>. Never use accounts of real users or your own personal accounts.</li><li>Provide <strong>at least two accounts per role</strong>. Agents need two accounts to prove that one user can access another user&#39;s data.</li><li>Provide accounts for <strong>every role</strong> the application has, including administrators.</li><li>Agents may change the data of these accounts. They are told to keep the accounts usable, but plan for a reset after the test.</li></ul><div class="warning custom-block"><p class="custom-block-title">Missing administrative accounts cost time</p><p>Without administrative accounts, agents cannot see the administrative functionality. They spend the <a href="/getting-started/pentest-not-a-scan">time box</a> guessing at admin endpoints instead of testing them, and authorization checks between normal users and administrators stay largely untested. The test becomes slower and less efficient. The same might apply to other missing roles.</p></div><h2 id="lockout-testing" tabindex="-1">Lockout testing <a class="header-anchor" href="#lockout-testing" aria-label="Permalink to &quot;Lockout testing&quot;">​</a></h2><p>By default, agents protect the provided accounts: they do not lock them out, change their passwords or exhaust MFA attempts, and they prove missing brute-force protection with a small number of attempts only.</p><p>The <strong>Lockout testing</strong> switch on the <strong>Overview</strong> tab allows destructive authentication tests (account lockout, brute force, MFA exhaustion). Agents then still prefer throwaway accounts, but a provided account can end up locked. Only turn it on if that is acceptable.</p><h2 id="account-manager-optional" tabindex="-1">Account manager (optional) <a class="header-anchor" href="#account-manager-optional" aria-label="Permalink to &quot;Account manager (optional)&quot;">​</a></h2><p>If you give the agents an administrator account of the target application under <strong>Account manager</strong> on the <strong>Overview</strong> tab, they can create fresh accounts, unlock locked accounts and get throwaway accounts for destructive tests on their own. The accounts created this way are listed under <strong>Managed accounts</strong>.</p><p>The administrator credential is used by an agent in the application&#39;s admin interface and is processed by the AI model like any other credential.</p><h2 id="side-effects-to-expect" tabindex="-1">Side effects to expect <a class="header-anchor" href="#side-effects-to-expect" aria-label="Permalink to &quot;Side effects to expect&quot;">​</a></h2><p>Tell the system owner to expect, among others:</p><ul><li>new, changed and deleted records created by the agents;</li><li>emails, notifications and password reset messages triggered by the application;</li><li>locked accounts (with lockout testing on, or after many failed logins);</li><li>entries in logs and alerts in monitoring or intrusion detection systems;</li><li>increased load during the run.</li></ul><h2 id="checklist" tabindex="-1">Checklist <a class="header-anchor" href="#checklist" aria-label="Permalink to &quot;Checklist&quot;">​</a></h2><ul class="contains-task-list"><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> The target is a staging system with test data, or production testing is explicitly agreed.</li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> The staging system sends emails (for example password reset) to mailboxes I can access, and payments use the provider&#39;s sandbox.</li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> I provided dedicated test accounts for every role, including administrators, at least two per role, and no real user accounts.</li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> Lockout testing is only on if locked accounts are acceptable.</li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> The system owner knows which side effects to expect and how to reset the system afterwards.</li></ul>`,25)])])}const g=e(o,[["render",i]]);export{p as __pageData,g as default};
